400	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
401	pub enum SpellFilter {
402	    /// All creature spells.
403	    CreatureSpells,
404	    /// Creature spells with a specific subtype.
405	    CreatureWithSubtype(String),
406	}
