409	mod tests {
410	    use super::*;
411	
412	    #[test]
413	    fn mana_cost_value() {
414	        // {2}{R}{R} = 4
415	        let cost = ManaCost::new(vec![
416	            ManaSymbol::Generic(2),
417	            ManaSymbol::Colored(Color::Red),
418	            ManaSymbol::Colored(Color::Red),
419	        ]);
420	        assert_eq!(cost.mana_value(), 4);
