424	    fn mana_cost_colored_requirements() {
425	        let cost = ManaCost::new(vec![
426	            ManaSymbol::Generic(1),
427	            ManaSymbol::Colored(Color::Green),
428	            ManaSymbol::Colored(Color::Green),
429	        ]);
430	        let reqs = cost.colored_requirements();
431	        assert_eq!(reqs.get(&Color::Green), Some(&2));
432	        assert_eq!(cost.generic_amount(), 1);
433	    }
434	
435	    #[test]
436	    fn mana_cost_display() {
437	        let cost = ManaCost::new(vec![
438	            ManaSymbol::Generic(2),
439	            ManaSymbol::Colored(Color::Red),
440	        ]);
441	        assert_eq!(format!("{}", cost), "{2}{R}");
442	    }
443	
444	    #[test]
445	    fn mana_pool_operations() {
446	        let mut pool = ManaPool::new();
447	        assert!(pool.is_empty());
448	
449	        pool.add(ManaType::Green, 2);
450	        pool.add(ManaType::Red, 1);
451	        assert_eq!(pool.total(), 3);
452	        assert_eq!(pool.get(ManaType::Green), 2);
453	        assert_eq!(pool.get(ManaType::Blue), 0);
454	
455	        pool.empty();
456	        assert!(pool.is_empty());
457	    }
458	
459	    #[test]
460	    fn step_progression() {
461	        let mut step = Step::Untap;
462	        let expected = vec![
463	            Step::Upkeep, Step::Draw, Step::PrecombatMain, Step::BeginCombat,
464	            Step::DeclareAttackers, Step::DeclareBlockers, Step::CombatDamage,
465	            Step::EndCombat, Step::PostcombatMain, Step::EndStep, Step::Cleanup,
466	        ];
467	        for expected_step in expected {
468	            step = step.next().unwrap();
469	            assert_eq!(step, expected_step);
470	        }
471	        assert!(step.next().is_none());
472	    }
473	}
