8	fn is_target_legal(state: &GameState, target: &Target, target_req: &crate::cards::TargetRequirement) -> bool {
9	    use crate::cards::TargetRequirement;
10	
11	    // ModalChoice: legal if legal under any mode.
12	    if let TargetRequirement::ModalChoice(ref modes) = target_req {
13	        return modes.iter().any(|mode_req| is_target_legal(state, target, mode_req));
14	    }
