16	    // Unwrap nested requirements (UpToTargets, TwoTargets).
17	    let inner_req = match target_req {
18	        TargetRequirement::UpToTargets(_, inner) => inner.as_ref(),
19	        TargetRequirement::TwoTargets(inner, _) => inner.as_ref(),
